"""Compare native FULL host eviction methods on identical CPU candidates."""

import ast
from collections import defaultdict
import gc
import hashlib
import json
from pathlib import Path
import statistics
import subprocess
import time
from types import MethodType, SimpleNamespace as NS

from sglang.srt.mem_cache.unified_cache.components import full as module
from sglang.srt.mem_cache.evict_policy import LRUStrategy

ROOT = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
ENGINE = ROOT / "third_party/sglang-v0.5.20"
SOURCE = Path("python/sglang/srt/mem_cache/unified_cache/components/full.py")
OUTPUT = ROOT / "experiments/reports/v267_full_host_reclaim_cpu_gc_controlled_20261013.json"
if OUTPUT.exists():
    raise ValueError("preserve prior evidence")
baseline = subprocess.check_output(["git", "show", f"HEAD:{SOURCE}"], cwd=ENGINE, text=True)
current = (ENGINE / SOURCE).read_text()


def method(source):
    tree = ast.parse(source)
    cls = next(node for node in tree.body if isinstance(node, ast.ClassDef)
               and node.name == "FullComponent")
    function = next(node for node in cls.body if isinstance(node, ast.FunctionDef)
                    and node.name == "drive_host_eviction")
    code = ast.Module(body=[
        ast.ImportFrom(module="__future__", names=[ast.alias(name="annotations")], level=0),
        function,
    ], type_ignores=[])
    namespace = dict(vars(module))
    exec(compile(ast.fix_missing_locations(code), "<full-host-eviction>", "exec"), namespace)
    return namespace["drive_host_eviction"]


class Node(NS):
    __hash__ = object.__hash__

    def __lt__(self, other):
        return self.id < other.id


def fixture(count, selected):
    component = module.FullComponent(NS(enable_session_radix_cache=True), None)
    nodes = {
        Node(id=i, parent=None, component_data={0: NS(session_ref=i % 3)},
             last_access_time=float(i)) for i in range(count)
    }

    def evict(node, tracker, device_frees, host_frees):
        nodes.remove(node)
        tracker[0] += 1
        selected.append(node.id)

    component.tree_core = NS(
        evictable_host_leaves=nodes, eviction_strategy=LRUStrategy(),
        _evict_host_leaf=evict,
    )
    return component


methods = {"baseline": method(baseline), "optimized": method(current)}
cases = []
for candidates in (0, 256, 4096, 32768):
    for satisfied in (True, False):
        if not candidates and not satisfied:
            continue
        clocks = {name: {"cpu": [], "wall": []} for name in methods}
        for iteration in range(33):
            outcomes = {}
            names = list(methods)
            if iteration % 2:
                names.reverse()
            for name in names:
                selected = []
                component = fixture(candidates, selected)
                component.drive_host_eviction = MethodType(methods[name], component)
                tracker = defaultdict(int, {0: 2 if satisfied else 0})
                device_frees, host_frees = defaultdict(list), defaultdict(list)
                was_enabled = gc.isenabled()
                gc.disable()
                try:
                    cpu, wall = time.thread_time_ns(), time.perf_counter_ns()
                    component.drive_host_eviction(1, tracker, device_frees, host_frees)
                    elapsed_wall = (time.perf_counter_ns() - wall) / 1e6
                    elapsed_cpu = (time.thread_time_ns() - cpu) / 1e6
                finally:
                    if was_enabled:
                        gc.enable()
                outcomes[name] = (dict(tracker), tuple(selected), len(component.tree_core.evictable_host_leaves))
                if iteration >= 3:
                    clocks[name]["cpu"].append(elapsed_cpu)
                    clocks[name]["wall"].append(elapsed_wall)
            assert outcomes["baseline"] == outcomes["optimized"]
        cases.append({
            "host_leaf_candidates": candidates, "already_satisfied": satisfied,
            "iterations": 30, "identical_eviction_result": True,
            "costs_ms": {name: {
                clock: {"p50": statistics.median(values), "mean": statistics.mean(values)}
                for clock, values in costs.items()
            } for name, costs in clocks.items()},
        })
report = {
    "scope": (
        "Alternating native baseline/current FULL eviction methods; real session-aware "
        "priority, synthetic host-leaf sets, no DMA or GPU. Real tree/allocator and "
        "lock regressions run separately. Cyclic GC is disabled only in timed calls "
        "to exclude unrelated fixture collections. CPU savings are not JCT or throughput gains."
    ),
    "baseline_source_sha256": hashlib.sha256(baseline.encode()).hexdigest(),
    "optimized_source_sha256": hashlib.sha256(current.encode()).hexdigest(),
    "cases": cases, "deployed": False,
    "helper_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    "helper_utf8_source": Path(__file__).read_text(),
}
OUTPUT.write_text(json.dumps(report, indent=2) + "\n")
print(json.dumps({"output": str(OUTPUT), "cases": cases}, indent=2))
